GUARD_EVENT_RX = r"\bA SEND (?:THAT )?ENDED AT (?:A|THE) (?:\d+ s )?GUARD\b"
GUARD_EVENT_HEAD = r"^    \((\d+)\) THE [A-Z ]+'S \[(?:CLAIM|CLOSE) ; [^\]]+\]: (.*)$"
